use rand::{SeedableRng, rngs::StdRng};
use crate::box_muller::normal_variable;

/// Parameters of a random walk: each step adds a N(mean, std_dev^2) increment
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MonteCarloParameters {
    /// Number of paths generated by generate_paths
    pub paths_number: usize,
    pub steps_number: usize,
    pub mean: f64,
    pub std_dev: f64,
    pub seed: u64,
}

/// Simulated path: the level of the walk after each step
#[derive(Debug, Clone, PartialEq)]
pub struct Path {
    pub returns: Vec<f64>,
}

fn generate_path(rng: &mut StdRng, params: &MonteCarloParameters) -> Path {
    let mut returns = Vec::with_capacity(params.steps_number);
    let mut level = 0.0;
    for _ in 0..params.steps_number {
        level += normal_variable(rng, params.mean, params.std_dev);
        returns.push(level);
    }
    Path { returns }
}

pub fn generate_paths(params: &MonteCarloParameters) -> Vec<Path> {
    let mut rng = StdRng::seed_from_u64(params.seed);
    let mut paths = Vec::with_capacity(params.paths_number);
    for _ in 0..params.paths_number {
        let path = generate_path(&mut rng, params);
        paths.push(path);
    }
    paths
}
